    n = len(nums)
    max_sum = float('-inf')
    current_sum = 0
    count = defaultdict(int)

    left = 0
    for right in range(n):
        count[nums[right]] += 1
        current_sum += nums[right]

        while len(count) > k:
            count[nums[left]] -= 1
            if count[nums[left]] == 0:
                del count[nums[left]]
            current_sum -= nums[left]
            left += 1

        max_sum = max(max_sum, current_sum)

    return max_sum
