public List<Integer> getDeepestLeaves(TreeNode root) {
    List<Integer> deepestLeaves = new ArrayList<>();
    if (root == null) {
        return deepestLeaves;
    }

    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);

    while (!queue.isEmpty()) {
        int size = queue.size();
        deepestLeaves.clear();

        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            deepestLeaves.add(node.val);

            if (node.left != null) {
