import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public List<List<Integer>> verticalOrder(TreeNode root) {
        if (root == null) return new ArrayList<>();

        HashMap<Integer, List<Integer>> columnTable = new HashMap<>();
        Queue<Pair<TreeNode, Integer>> q = new LinkedList<>();
        q.offer(new Pair<>(root, 0));

        while (!q.isEmpty()) {
            TreeNode curNode = q.peek().getKey();
            int column = q.peek().getValue();
            q.poll();

            if (curNode != null) {
                columnTable.putIfAbsent(column, new ArrayList<>());
                columnTable.get(column).add(curNode.val);
                q.offer(new Pair<>(curNode.left, column - 1));
                q.offer(new Pair<>(curNode.right, column + 1));
            }
        }

        return new ArrayList<>(columnTable.values());
    }

    public int findMinVerticalSum(TreeNode root) {
        if (root == null) return 0;

        HashMap<Integer, Integer> columnSum = new HashMap<>();
        Queue<Pair<TreeNode, Integer>> q = new LinkedList<>();
        q.offer(new Pair<>(root, 0));

        while (!q.isEmpty()) {
            TreeNode curNode = q.peek().getKey();
            int column = q.peek().getValue();
            q.poll();

            if (curNode != null) {
                columnSum.put(column, columnSum.getOrDefault(column, 0) + curNode.val);
                q.offer(new Pair<>(curNode.left, column - 1));
                q.offer(new Pair<>(curNode.right, column + 1));
            }
        }

        int minSum = Integer.MAX_VALUE;
        for (int sum : columnSum.values()) {
            minSum = Math.min(minSum, sum);
        }

        return minSum;
    }
}
