    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '1') {
                numIslands++;
                queue<pair<int, int>> q;
                q.push({i, j});
                grid[i][j] = '0';

                while (!q.empty()) {
                    int x = q.front().first;
                    int y = q.front().second;
                    q.pop();

                    if (x - 1 >= 0 && grid[x - 1][y] == '1') {
                        q.push({x - 1, y});
                        grid[x - 1][y] = '0';
                    }
                    if (x + 1 < rows && grid[x + 1][y] == '1') {
                        q.push({x + 1, y});
                        grid[x + 1][y] = '0';
