                    if (y - 1 >= 0 && grid[x][y - 1] == '1') {
                        q.push({x, y - 1});
                        grid[x][y - 1] = '0';
                    }
                    if (y + 1 < cols && grid[x][y + 1] == '1') {
                        q.push({x, y + 1});
                        grid[x][y + 1] = '0';
