public int countRestrictedPaths(int n, int[][] edges, int[] restricted) {
    List<int[]>[] graph = new List[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0] - 1, v = edge[1] - 1, w = edge[2];
        graph[u].add(new int[]{v, w});
        graph[v].add(new int[]{u, w});
    }
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[n - 1] = 0;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
    pq.offer(new int[]{n - 1, 0});
    while (!pq.isEmpty()) {
        int[] curr = pq.poll();
        int u = curr[0], d = curr[1];
        if (d > dist[u]) {
            continue;
        }
        for (int[] next : graph[u]) {
            int v = next[0], w = next[1];
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.offer(new int[]{v, dist[v]});
            }
        }
    }
    int[] dp = new int[n];
    Arrays.fill(dp, -1);
    return dfs(graph, dist, dp, 0);
}

private int dfs(List<int[]>[] graph, int[] dist, int[] dp, int u) {
    if (dp[u] != -1) {
        return dp[u];
    }
    if (u == graph.length - 1) {
        return 1;
    }
    int res = 0;
    for (int[] next : graph[u]) {
        int v = next[0];
        if (dist[v] < dist[u]) {
            res += dfs(graph, dist, dp, v);
        }
    }
    dp[u] = res;
    return res;
}
