    public int[] maxNodesWithoutRestricted(int[][] grid, int[] queries) {
        int m = grid.length, n = grid[0].length;
        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int query = queries[i];
            int maxNodes = 0;
            boolean[][] visited = new boolean[m][n];
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < n; k++) {
                    if (grid[j][k] == query && !visited[j][k]) {
                        maxNodes = Math.max(maxNodes, dfs(grid, j, k, visited, dirs));
                    }
                }
            }
            result[i] = maxNodes;
        }
        return result;
    }

    private int dfs(int[][] grid, int i, int j, boolean[][] visited, int[][] dirs) {
