        for (int j = 0; j < i; ++j) {
            std::string word = s.substr(j, i - j);
            if (dp[j].size() > 0 && wordSet.find(word) != wordSet.end()) {
                for (const std::string& prev : dp[j]) {
                    dp[i].push_back(prev + (prev.empty() ? "" : " ") + word);
