import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> findSubsequence(int[] nums, int k) {
        List<Integer> result = new ArrayList<>();
        if (nums == null || nums.length == 0 || k <= 0) {
            return result;
        }
        int n = nums.length;
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];
                if (nums[i - 1] > dp[i - 1][j - 1]) {
                    dp[i][j] = nums[i - 1];
                }
            }
        }
        int i = n, j = k;
        while (i > 0 && j > 0) {
            if (dp[i][j] == dp[i - 1][j]) {
                i--;
            } else {
                result.add(0, nums[i - 1]);
                i--;
                j--;
            }
        }
        return result;
    }
}
