int smallestDistancePair(std::vector<int>& nums, int k) {
    std::sort(nums.begin(), nums.end());
    int low = 0, high = nums.back() - nums.front();

    while (low < high) {
        int mid = (low + high) / 2;
        int count = 0, left = 0;

        for (int right = 0; right < nums.size(); ++right) {
            while (nums[right] - nums[left] > mid) {
                ++left;
            }
            count += (right - left);
