import java.util.HashMap;
import java.util.HashSet;

public class Solution {
    public boolean uniqueOccurrences(int[] arr) {
        HashMap<Integer, Integer> counts = new HashMap<>();
        for (int num : arr) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        HashSet<Integer> uniqueCounts = new HashSet<>();
        for (int count : counts.values()) {
            if (uniqueCounts.contains(count)) {
                return false;
            }
            uniqueCounts.add(count);
        }

        return true;
    }

    public boolean isGraphConnected(int n, int[][] edges) {
        HashMap<Integer, HashSet<Integer>> graph = new HashMap<>();
        for (int i = 0; i < n; i++) {
            graph.put(i, new HashSet<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        HashSet<Integer> visited = new HashSet<>();
        dfs(graph, 0, visited);

        return visited.size() == n;
    }

    private void dfs(HashMap<Integer, HashSet<Integer>> graph, int node, HashSet<Integer> visited) {
        visited.add(node);

        for (int neighbor : graph.get(node)) {
            if (!visited.contains(neighbor)) {
                dfs(graph, neighbor, visited);
            }
        }
    }
}
```

