plt.plot(optimal_point, objective_function(optimal_point), 'ro')
plt.xlabel('x')
plt.ylabel('f(x)')
plt.title('Gradient Descent Optimization')
plt.show()

# Print the optimal point and the minimum value of the function
print('Optimal point:', optimal_point)
print('Minimum value:', objective_function(optimal_point))
