            if (contained) {
                for (int i = bounds[0]; i <= bounds[2]; ++i) {
                    for (int j = bounds[1]; j <= bounds[3]; ++j) {
                        targetGrid[i][j] = -1;
                    }
                }
                it.remove();
                progress = true;
            }
        }
        if (!progress) return false;
    }
    return true;
}
