std::vector<std::vector<int>> buildMatrix(int k, std::vector<std::vector<int>>& rowConditions, std::vector<std::vector<int>>& colConditions) {
    std::vector<std::vector<int>> result(k, std::vector<int>(k, 0));
    std::unordered_map<int, std::vector<int>> row_graph, col_graph;
    std::unordered_map<int, int> row_indegree, col_indegree;
    std::set<int> row_remaining, col_remaining;

    // Build row and column graphs and calculate indegrees
    for (const auto& condition : rowConditions) {
        row_graph[condition[0]].push_back(condition[1]);
        row_indegree[condition[1]]++;
    }
    for (const auto& condition : colConditions) {
        col_graph[condition[0]].push_back(condition[1]);
        col_indegree[condition[1]]++;
    }

    // Initialize remaining sets
    for (int i = 1; i <= k; ++i) {
        row_remaining.insert(i);
        col_remaining.insert(i);
    }

    // Topological sort for rows
    while (!row_remaining.empty()) {
        bool progress = false;
        for (auto it = row_remaining.begin(); it != row_remaining.end();) {
            int color = *it;
