                it = row_remaining.erase(it);
                progress = true;
            } else {
                ++it;
            }
        }
        if (!progress) return {};
    }

    // Topological sort for columns
    while (!col_remaining.empty()) {
        bool progress = false;
        for (auto it = col_remaining.begin(); it != col_remaining.end();) {
