bool isPalindrome(ListNode* head) {
    if (!head || !head->next) return true;

    ListNode *fast = head, *slow = head, *prev = NULL;
    while (fast && fast->next) {
        fast = fast->next->next;
        ListNode *temp = slow->next;
        slow->next = prev;
        prev = slow;
        slow = temp;
    }

    if (fast) slow = slow->next;

    while (prev && prev->val == slow->val) {
        prev = prev->next;
        slow = slow->next;
    }

    return prev == NULL;
}
