    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> result = new ArrayList<>();
        if (s == null || s.length() == 0 || words == null || words.length == 0) {
            return result;
        }

        int wordLength = words[0].length();
        int totalLength = wordLength * words.length;
        HashMap<String, Integer> wordCount = new HashMap<>();
        for (String word : words) {
            wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
        }

        for (int i = 0; i < wordLength; i++) {
            HashMap<String, Integer> windowCount = new HashMap<>();
            int left = i, right = i, count = 0;
            while (right + wordLength <= s.length()) {
                String word = s.substring(right, right + wordLength);
                right += wordLength;
                if (wordCount.containsKey(word)) {
                    windowCount.put(word, windowCount.getOrDefault(word, 0) + 1);
                    if (windowCount.get(word) <= wordCount.get(word)) {
                        count++;
                    }
                    while (count == words.length) {
                        if (right - left == totalLength) {
                            result.add(left);
                        }
                        String leftWord = s.substring(left, left + wordLength);
                        left += wordLength;
                        if (wordCount.containsKey(leftWord)) {
