    Solution solution = new Solution();

    String s1 = "abcabcbb";
    int result1 = solution.lengthOfLongestSubstring(s1);
    System.out.println(result1); // Output: 3

    String s2 = "bbbbb";
    int result2 = solution.lengthOfLongestSubstring(s2);
    System.out.println(result2); // Output: 1

    String s3 = "pwwkew";
    int result3 = solution.lengthOfLongestSubstring(s3);
    System.out.println(result3); // Output: 3
}
```

