# 1690. 石子游戏 VII
# https://leetcode.cn/problems/stone-game-vii/

# Alice 和 Bob 一起玩游戏，他们轮流行动。在游戏过程中，他们共同使用一副扑克牌，牌上写有 1 到 N 的整数（大写和小写）。

# 游戏由 2 轮组成：洗牌的阶段 和平局的阶段。洗牌的阶段按照下述规则进行：

# 重新洗牌包含牌 deck
# 洗牌后，从牌堆顶部取一张牌，先交给 Alice ，然后给 Bob
# 重复这个过程，以确定 Alice 和 Bob 的拿牌顺序
# 平局的阶段按照下述规则进行：

# Alice 先从牌堆顶部取一张牌，然后 Bob 取第二张牌
# Alice 取第三张牌，然后 Bob 取第四张牌
# 重复这个过程，以确定 Alice 和 Bob 的得分
# 得分高的玩家赢得这场游戏。如果两位玩家得分相同，那么这个游戏就会以平局结束。

# Alice 和 Bob 都会尽力赢得游戏。Alice 总是先开始洗牌。

# 给你牌堆 deck ，请你返回 Alice 和 Bob 能够获得的最大分差。

# 示例 1：

# 输入：deck = [1,2,3,4,5,6,1,6]
# 输出：0
# 解释：
# Alice 拿牌 [1,3,5,6] ，Bob 拿牌 [2,4,1,6]
# Alice 得分 1+5+6=12 ，Bob 的得分 2+4+1=7 ，Bob 获胜
# 示例 2：

# 输入：deck = [3,2,10,4,3]
# 输出：-1
# 解释：
# Alice 拿牌 [3,2,3] ，Bob 拿牌 [10,4]
# Alice 得分 3+2+3=8 ，Bob 的得分 10+4=14 ，Bob 获胜

# 提示：

# 1 <= deck.length <= 10^5
# 0 <= deck[i] <= 10^6

from typing import List
from collections import Counter

class Solution:
    def stoneGameVII(self, deck: List[int]) -> int:
        n = len(deck)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + deck[i]

        dp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                dp[i][j] = max(prefix_sum[j + 1] - prefix_sum[i + 1] - dp[i + 1][j], prefix_sum[j] - prefix_sum[i] - dp[i][j - 1])

        return dp[0][n - 1]

