# 1002. Find Common Characters

# Given a string array words, return an array of all characters that show up in all strings within the words (including duplicates). You may return the answer in any order.

# Example 1:
# Input: words = ["bella","label","roller"]
# Output: ["e","l","l"]

# Example 2:
# Input: words = ["cool","lock","cook"]
# Output: ["c","o"]

# Constraints:
# 1 <= words.length <= 100
# 1 <= words[i].length <= 100
# words[i] consists of lowercase English letters.

# Solution
# Time Complexity: O(n * m), where n is the number of words and m is the average length of the words
# Space Complexity: O(1), since the size of the alphabet is constant (26)

from typing import List

class Solution:
    def commonChars(self, words: List[str]) -> List[str]:
        # Initialize a list to store the count of each character in the first word
        char_count = [0] * 26

        # Iterate over each character in the first word
        for char in words[0]:
            # Increment the count of the character in the char_count list
            char_count[ord(char) - ord('a')] += 1

        # Iterate over the remaining words
        for word in words[1:]:
            # Initialize a list to store the count of each character in the current word
            current_count = [0] * 26

            # Iterate over each character in the current word
            for char in word:
                # Increment the count of the character in the current_count list
                current_count[ord(char) - ord('a')] += 1

            # Update the char_count list by taking the minimum count of each character
            for i in range(26):
                char_count[i] = min(char_count[i], current_count[i])

        # Initialize a list to store the common characters
        common_chars = []

        # Iterate over each character in the alphabet
        for i in range(26):
            # If the count of the character is greater than 0, add it to the common_chars list
            if char_count[i] > 0:
                common_chars.extend([chr(i + ord('a'))] * char_count[i])

        # Return the list of common characters
        return common_chars

