    n = len(s)
    maxLength = 0
    lastSeen = {}
    i = 0
    for j in range(n):
        if s[j] in lastSeen:
            i = max(i, lastSeen[s[j]])
        maxLength = max(maxLength, j - i + 1)
        lastSeen[s[j]] = j + 1
    return maxLength
```

