public int countUniqueSubarrays(int[] nums) {
    int n = nums.length;
    int[] dp = new int[n];
    dp[0] = 1;
    int count = 1;
    for (int i = 1; i < n; ++i) {
        if (nums[i] != nums[i - 1]) {
            dp[i] = dp[i - 1] + 1;
            count += dp[i];
        } else {
            dp[i] = 1;
            count += dp[i];
        }
    }
    return count;
}
