public int minCost(int[][] costs) {
    if (costs.length == 0) return 0;
    int n = costs.length;
    int k = costs[0].length;
    int[][] dp = new int[n][k];
    for (int i = 0; i < k; ++i) {
        dp[0][i] = costs[0][i];
    }
    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < k; ++j) {
            int min = Integer.MAX_VALUE;
            for (int l = 0; l < k; ++l) {
                if (l != j) {
                    min = Math.min(min, dp[i - 1][l]);
                }
            }
            dp[i][j] = min + costs[i][j];
        }
    }
    int min = Integer.MAX_VALUE;
    for (int i = 0; i < k; ++i) {
        min = Math.min(min, dp[n - 1][i]);
    }
    return min;
}
