from typing import List
from functools import lru_cache

class Solution:
    def stoneGameVII(self, stones: List[int]) -> int:
        n = len(stones)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + stones[i]

        @lru_cache(None)
        def dfs(i, j):
            if i == j:
                return 0
            return max(prefix_sum[j + 1] - prefix_sum[i + 1] - dfs(i + 1, j), prefix_sum[j] - prefix_sum[i] - dfs(i, j - 1))

        return dfs(0, n - 1)

