### Solution
```python
def max_product_of_subarrays(arr):
    n = len(arr)
    max_product = float('-inf')
    left_max = [0] * n
    right_max = [0] * n
    left_max[0] = arr[0]
    right_max[n-1] = arr[n-1]
    for i in range(1, n):
        left_max[i] = max(arr[i], left_max[i-1] * arr[i])
        right_max[n-i-1] = max(arr[n-i-1], right_max[n-i] * arr[n-i-1])
    for i in range(n-1):
        max_product = max(max_product, left_max[i] * right_max[i+1])
    return max_product
```

