public class Solution {
    public List<Integer> findPermutations(int n, int k) {
        List<Integer> res = new ArrayList<>();
        boolean[] visited = new boolean[n+1];
        helper(n, k, 1, visited, res);
        return res;
    }

    private void helper(int n, int k, int idx, boolean[] visited, List<Integer> res) {
        if (res.size() == k) {
            return;
