using namespace std;

struct Node {
    bool val;
    bool isLeaf;
    Node* topLeft;
    Node* topRight;
    Node* bottomLeft;
    Node* bottomRight;
};

Node* construct(vector<vector<int>>& grid) {
    return helper(grid, 0, 0, grid.size());
}

Node* helper(vector<vector<int>>& grid, int x, int y, int length) {
    if (length == 1) {
        return new Node{grid[x][y] == 1, true, nullptr, nullptr, nullptr, nullptr};
    }

    Node* tl = helper(grid, x, y, length / 2);
    Node* tr = helper(grid, x, y + length / 2, length / 2);
    Node* bl = helper(grid, x + length / 2, y, length / 2);
    Node* br = helper(grid, x + length / 2, y + length / 2, length / 2);

    if (tl->isLeaf && tr->isLeaf && bl->isLeaf && br->isLeaf &&
        tl->val == tr->val && tr->val == bl->val && bl->val == br->val) {
        bool value = tl->val;
        delete tl;
        delete tr;
        delete bl;
        delete br;
        return new Node{value, true, nullptr, nullptr, nullptr, nullptr};
    } else {
        return new Node{false, false, tl, tr, bl, br};
    }
}

vector<string> basicCalculatorIV(string expression, vector<string>& evalvars, vector<int>& evalints) {
    unordered_map<string, int> vars;
    for (int i = 0; i < evalvars.size(); i++) {
        vars[evalvars[i]] = evalints[i];
    }

    vector<string> tokens = tokenize(expression);
    vector<string> postfix = infixToPostfix(tokens, vars);

    stack<Node*> stack;
    for (string token : postfix) {
        if (vars.find(token) != vars.end()) {
            stack.push(new Node{vars[token] == 1, true, nullptr, nullptr, nullptr, nullptr});
        } else if (token == "+") {
            Node* right = stack.top();
            stack.pop();
            Node* left = stack.top();
            stack.pop();
            stack.push(new Node{left->val || right->val, false, left, right, nullptr, nullptr});
        } else if (token == "-") {
            Node* right = stack.top();
            stack.pop();
            Node* left = stack.top();
            stack.pop();
            stack.push(new Node{left->val && !right->val, false, left, right, nullptr, nullptr});
        } else if (token == "*") {
            Node* right = stack.top();
            stack.pop();
            Node* left = stack.top();
            stack.pop();
            stack.push(new Node{left->val && right->val, false, left, right, nullptr, nullptr});
        } else {
            stack.push(new Node{token == "1", true, nullptr, nullptr, nullptr, nullptr});
        }
    }

    Node* root = stack.top();
    stack.pop();

    vector<string> result;
    dfs(root, result);
    return result;
}

vector<string> tokenize(string expression) {
    vector<string> tokens;
    string token;
    for (char c : expression) {
        if (c == ' ') {
            continue;
        } else if (c == '+' || c == '-' || c == '*') {
            tokens.push_back(token);
            token.clear();
            tokens.push_back(string(1, c));
        } else {
            token += c;
        }
    }
    tokens.push_back(token);
    return tokens;
}

vector<string> infixToPostfix(vector<string>& tokens, unordered_map<string, int>& vars) {
    vector<string> postfix;
    stack<string> operators;
    for (string token : tokens) {
        if (vars.find(token) != vars.end()) {
            postfix.push_back(token);
        } else if (token == "+" || token == "-" || token == "*") {
            while (!operators.empty() && operators.top() != "(") {
                postfix.push_back(operators.top());
                operators.pop();
            }
            operators.push(token);
        } else if (token == "(") {
            operators.push(token);
        } else if (token == ")") {
            while (!operators.empty() && operators.top() != "(") {
                postfix.push_back(operators.top());
                operators.pop();
            }
            operators.pop();
        }
    }
    while (!operators.empty()) {
        postfix.push_back(operators.top());
        operators.pop();
    }
    return postfix;
}

void dfs(Node* node, vector<string>& result) {
    if (node->isLeaf) {
        result.push_back(node->val ? "1" : "0");
    } else {
        dfs(node->topLeft, result);
        dfs(node->topRight, result);
        dfs(node->bottomLeft, result);
        dfs(node->bottomRight, result);
    }
}

