    string expression = "e + 8 - a + 5";
    vector<string> evalvars = {"e"};
    vector<int> evalints = {1};
    vector<string> result = basicCalculatorIV(expression, evalvars, evalints);
    for (string s : result) {
        cout << s << endl;
    }
    return 0;
}
